"""Contact sheet for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not student.email:
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def _name(student: Student) -> str:
    return student.display_name


def _cells(student: Student) -> List[str]:
    return [
        student.display_name, student.section, student.email
    ]


def _line(cells: List[str], widths: List[int]) -> str:
    pairs = zip(cells, widths)
    padded = [cell.ljust(size) for cell, size in pairs]
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, by name."""
    roster = sorted(students, key=_name)
    _check(roster)
    table = [_cells(stud) for stud in roster]
    widths = [max(map(len, col)) for col in zip(*table)]
    return [_line(row, widths) for row in table]
